import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    n, m = data[0], data[1]
    sums = [0] * m

    idx = 2
    for _ in range(n):
        for j in range(m):
            sums[j] += data[idx]
            idx += 1

    print(min(sums))

if __name__ == "__main__":
    main()
